(G/'index.html').write_text(page,encoding='utf8');(G/'gallery-status.json').write_text(json.dumps({'selected_images':16,'dimensions':[1254,1254],'alpha_preserved':True,'zip_files':16,'trellis_executed':False,'environment_status':'layout_reference_only_requires_asset_decomposition','vehicle_status':'single_asset_candidates_unverified'},indent=2));print('IMAGE_GALLERY_READY',json.dumps({'images':16,'archive_bytes':archive.stat().st_size,'path':str(G)}),flush=True)
